import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { FaTimes, FaExclamationTriangle } from 'react-icons/fa';
import axios from 'axios';
import './AddMealModal.css';

const AddMealModal = ({ selectedUser, onClose, onMealAdded, existingMeals }) => {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [duplicateWarning, setDuplicateWarning] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!name.trim()) {
      setError('שם הארוחה הוא שדה חובה');
      return;
    }

    try {
      setLoading(true);
      setError('');
      setDuplicateWarning(null);

      const response = await axios.post('/api/meals', {
        name: name.trim(),
        description: description.trim(),
        userId: selectedUser.id
      });

      onMealAdded();
    } catch (err) {
      if (err.response?.status === 409) {
        // Duplicate item warning
        setDuplicateWarning(err.response.data.existingItem);
        setError('ארוחה זו כבר קיימת במערכת');
      } else {
        setError('שגיאה בהוספת הארוחה');
        console.error('Error adding meal:', err);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleNameChange = (e) => {
    const newName = e.target.value;
    setName(newName);

    // Check for duplicates in existing meals
    if (newName.trim()) {
      const duplicate = existingMeals.find(
        meal => meal.name.toLowerCase() === newName.toLowerCase()
      );

      if (duplicate) {
        setDuplicateWarning({
          name: duplicate.name,
          user_name: duplicate.user_name,
          user_color: duplicate.user_color
        });
      } else {
        setDuplicateWarning(null);
      }
    } else {
      setDuplicateWarning(null);
    }

    setError('');
  };

  return (
    <AnimatePresence>
      <motion.div
        className="modal-overlay"
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        onClick={onClose}
      >
        <motion.div
          className="modal-content"
          initial={{ opacity: 0, scale: 0.8, y: 50 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.8, y: 50 }}
          onClick={(e) => e.stopPropagation()}
        >
          <div className="modal-header">
            <h2>הוסף ארוחה חדשה</h2>
            <button className="close-button" onClick={onClose}>
              <FaTimes />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="modal-form">
            <div className="form-group">
              <label htmlFor="name">שם הארוחה</label>
              <input
                type="text"
                id="name"
                value={name}
                onChange={handleNameChange}
                placeholder="הכנס שם ארוחה"
                className="form-input"
                disabled={loading}
              />
            </div>

            <div className="form-group">
              <label htmlFor="description">תיאור (אופציונלי)</label>
              <textarea
                id="description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="הוסף תיאור לארוחה..."
                className="form-textarea"
                rows="3"
                disabled={loading}
              />
            </div>

            {duplicateWarning && (
              <motion.div
                className="duplicate-warning"
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
              >
                <FaExclamationTriangle />
                <div className="warning-content">
                  <span className="warning-title">אזהרה: ארוחה דומה קיימת</span>
                  <div className="existing-item">
                    <div 
                      className="user-indicator" 
                      style={{ backgroundColor: duplicateWarning.user_color }}
                    >
                      <span>{duplicateWarning.user_name.charAt(0)}</span>
                    </div>
                    <span className="item-name">{duplicateWarning.name}</span>
                    <span className="item-user">על ידי {duplicateWarning.user_name}</span>
                  </div>
                </div>
              </motion.div>
            )}

            {error && (
              <motion.div
                className="error-message"
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
              >
                {error}
              </motion.div>
            )}

            <div className="modal-actions">
              <button
                type="button"
                className="cancel-button"
                onClick={onClose}
                disabled={loading}
              >
                ביטול
              </button>
              <button
                type="submit"
                className="submit-button"
                disabled={loading || !name.trim()}
              >
                {loading ? 'מוסיף...' : 'הוסף ארוחה'}
              </button>
            </div>
          </form>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

export default AddMealModal;
